/bin/zsh -lc "python3 - <<'PY'
from pathlib import Path
from html.parser import HTMLParser
import re
s=Path('index.html').read_text()
script=re.search(r'<script>([\\s\\S]*?)</script>',s).group(1)
Path('/tmp/kestrel-dashboard-check.js').write_text(script)
funcs=re.findall(r'"'^    function ('"\\w+)\\(',script,re.M)
assert len(funcs)==len(set(funcs)), 'Duplicate function declaration'
class Audit(HTMLParser):
 def __init__(self):super().__init__();self.ids=[];self.fragments=[]
 def handle_starttag(self,t,attrs):
  a=dict(attrs)
  if 'id' in a:self.ids.append(a['id'])
  if a.get('href','').startswith('#'):self.fragments.append(a['href'][1:])
a=Audit();a.feed(s)
assert len(a.ids)==len(set(a.ids))
assert set(a.fragments)<=set(a.ids)
print('Final static checks passed: unique functions and IDs, valid local references, responsive CSS, no external scripts or images.')
PY
node --check /tmp/kestrel-dashboard-check.js
node <<'JS'
const fs=require('fs'),vm=require('vm'),assert=require('assert');
const source=fs.readFileSync('/tmp/kestrel-dashboard-check.js','utf8');
const data=source.slice(source.indexOf('const revenue ='),source.indexOf('const "'$ ='"'));
const ctx={};vm.createContext(ctx);vm.runInContext(data+';globalThis.result={revenue,categories,cafes,products,orders,inventory};',ctx);
const d=JSON.parse(JSON.stringify(ctx.result));
assert.deepStrictEqual(d.revenue.map(r=>[r.online,r.cafes]),[[61,88],[74,102],[58,81],[60,84],[63,89],[66,93],[68,97],[70,99],[72,96],[75,95],[79,94],[83,101]]);
assert.deepStrictEqual(d.categories.map(r=>r.share),[38,27,14,12,6,3]);
assert.deepStrictEqual(d.cafes.map(r=>[r.revenue,r.orders,r.ticket,r.change]),[[31420,1812,17.34,4.8],[27960,1655,16.89,2.1],[24310,1498,16.23,-1.7],[17630,1127,15.64,9.6]]);
assert.deepStrictEqual(d.products.map(r=>[r.units,r.revenue]),[[1104,16008],[412,14420],[655,9170],[138,6210],[291,5529]]);
assert.deepStrictEqual(d.orders.map(r=>[r.id,r.customer,r.channel,r.items,r.total,r.status]),[['48213','Ana Ruiz','Online',2,41,'Shipped'],['48212','Tomás Berg','Harbor Street',3,14.75,'Paid'],['48211','Priya Nair','Online',1,35,'Pending'],['48210','Jonah Weiss','Mill Lane',2,9.4,'Paid'],['48209','Lena Okafor','Online',4,63.5,'Refunded'],['48208','Sam Choi','Riverside',1,5.25,'Paid']]);
assert.deepStrictEqual(d.inventory.map(r=>r.days),[6,14,3,21]);
console.log('Data audit passed: all chart, café, product, order, and inventory figures match the brief. JavaScript syntax check passed.');
JS"

